import io
import base64
import re
import hashlib
import unicodedata
import pandas as pd
import altair as alt
import streamlit as st
from evaluation_engine import evaluate_operator, DEFAULT_WEIGHTS

st.set_page_config(page_title="Avaliação Auto Drill", page_icon="⚙️", layout="wide")

# Banner incorporado para não depender de um arquivo de imagem no repositório.
AUTO_DRILL_BANNER = ""
st.image(base64.b64decode(AUTO_DRILL_BANNER), use_container_width=True)

st.caption("Importe a planilha exportada do Microsoft Forms. O sistema calcula aderência, coerência técnico-comportamental e apresenta os achados por operador.")


def normalize_header(value):
    text = unicodedata.normalize("NFKD", str(value))
    text = "".join(c for c in text if not unicodedata.combining(c))
    text = re.sub(r"auto[\s_-]*drill", "auto drill", text.lower())
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


def find_col(columns, needles):
    # Ignore question numbering: Forms titles can be renumbered.
    terms = [normalize_header(n) for n in needles if not normalize_header(n).isdigit()]
    matches = [c for c in columns if all(n in normalize_header(c) for n in terms)]
    # Ambiguous matches must be resolved by the user, never by column order.
    return matches[0] if len(matches) == 1 else None


COLUMN_PATTERNS = {
    "nome": [["nome completo"], ["nome"]],
    "q1": [["qual modo", "prefere", "durante a perfuracao"]],
    "q2": [["qual modo", "prefere", "durante o emboque"], ["qual modo", "prefere", "embocamento"]],
    "q3": [["por que", "emboque"], ["porque", "emboque"], ["justific", "emboque"], ["por que", "embocamento"]],
    "q4": [["maior chance", "desvio"]],
    "q5": [["apos", "estabiliza"]],
    "q6": [["qual modo", "melhor taxa de penetracao"]],
    "q7": [["qual modo", "controlar", "torque"]],
    "q8": [["influencia", "decisao", "utilizar", "modo manual"]],
    "q9": [["comportamento", "auto drill", "desvio"]],
    "q10": [["influencia", "decisao", "utilizar", "auto drill"]],
    "q11": [["evita", "auto drill"]],
    "q12": [["se respondeu", "condicao"]],
    "q13": [["aumentar", "confianca"]],
    "freq_manual": [["10 furos", "manual"]],
    "q14": [["pontos positivos", "negativos"]],
    "q15": [["mudar ou melhorar"]],
}

COLUMN_LABELS = {
    "nome": "Nome do operador", "q1": "Preferência de perfuração",
    "q2": "Preferência de emboque", "q3": "Justificativa do emboque",
    "q4": "Maior chance de desvio", "q5": "Após estabilização",
    "q6": "Taxa de penetração", "q7": "Controle de torque",
    "q8": "Modo manual", "q9": "Auto Drill diante de desvio",
    "q10": "Benefícios de utilizar Auto Drill", "q11": "Evita Auto Drill",
    "q12": "Condição para evitar Auto Drill", "q13": "Aumentar confiança",
    "freq_manual": "Frequência manual em 10 furos (opcional)",
    "q14": "Pontos positivos e negativos", "q15": "O que mudar ou melhorar",
}


def map_columns(df):
    mapping = {}
    for key, alternatives in COLUMN_PATTERNS.items():
        mapping[key] = None
        for terms in alternatives:
            candidate = find_col(df.columns, terms)
            if candidate is not None:
                mapping[key] = candidate
                break
    # A column cannot represent two different questions.
    for column in list(df.columns):
        keys = [key for key, value in mapping.items() if value == column]
        if len(keys) > 1:
            for key in keys:
                mapping[key] = None
    return mapping


def record_from_row(row, mapping):
    out = {}
    for k, c in mapping.items():
        out[k] = "" if c is None or pd.isna(row.get(c, "")) else str(row.get(c, ""))
    return out

with st.sidebar:
    st.header("Configuração")
    st.write("Os pesos de aderência podem ser ajustados sem alterar o motor de coerência.")
    weights = {}
    labels = {
        "q1_preferencia_perfuracao": "Q1 Preferência perfuração",
        "q2_preferencia_emboque": "Q2 Preferência emboque",
        "q3_justificativa_emboque": "Q3 Justificativa emboque",
        "q5_apos_estabilizacao": "Q5 Após estabilização",
        "q7_controle_torque": "Q7 Controle torque",
        "q10_beneficios_auto": "Q10 Benefícios Auto Drill",
        "q11q12_evitar_auto": "Q11/Q12 Evita Auto Drill",
    }
    for key, default in DEFAULT_WEIGHTS.items():
        weights[key] = st.number_input(labels[key], min_value=0, max_value=50, value=int(default), step=1)
    st.metric("Total de pesos", sum(weights.values()))
    if sum(weights.values()) != 100:
        st.info("O sistema normaliza a nota para 100%, mesmo se a soma dos pesos for diferente de 100.")

uploaded = st.file_uploader("Selecione a planilha do Microsoft Forms (.xlsx)", type=["xlsx"])

if uploaded:
    try:
        df = pd.read_excel(uploaded)
    except Exception as e:
        st.error(f"Não foi possível ler a planilha: {e}")
        st.stop()

    if not df.columns.is_unique:
        st.error("Há títulos de colunas duplicados. Diferencie os títulos na planilha e importe novamente.")
        st.stop()

    detected = map_columns(df)
    signature = 'mapping_v2_' + hashlib.sha256(uploaded.getvalue()).hexdigest()[:16]
    with st.expander("Conferir e corrigir identificação das perguntas", expanded=True):
        st.write("Confira o título completo de cada pergunta. Selecione a coluna correta quando necessário. Os códigos q1–q15 são internos e podem diferir da numeração do Forms.")
        mapping = {}
        options = [None] + list(df.columns)
        for key, candidate in detected.items():
            mapping[key] = st.selectbox(
                COLUMN_LABELS[key], options,
                index=options.index(candidate),
                format_func=lambda value: "— Selecione uma coluna —" if value is None else str(value),
                key=f"mapping_{signature}_{key}",
            )
        confirmed = st.checkbox("Conferi a correspondência entre as perguntas e as colunas", key=f"confirmed_{signature}")

    missing = [key for key, value in mapping.items() if value is None and key != "freq_manual"]
    assigned = [value for value in mapping.values() if value is not None]
    if missing:
        st.error("Identifique as perguntas antes de calcular: " + ", ".join(COLUMN_LABELS[key] for key in missing))
        st.stop()
    if len(assigned) != len(set(assigned)):
        st.error("Uma coluna foi selecionada para mais de uma pergunta. Corrija a correspondência antes de calcular.")
        st.stop()
    if not confirmed:
        st.info("Confirme a correspondência das perguntas para liberar a avaliação.")
        st.stop()
    if sum(weights.values()) <= 0:
        st.error("Defina pelo menos um peso maior que zero antes de calcular.")
        st.stop()

    results = []
    for _, row in df.iterrows():
        rec = record_from_row(row, mapping)
        if not rec.get("nome"):
            continue
        ev = evaluate_operator(rec, weights=weights)
        ev["_record"] = rec
        results.append(ev)

    if not results:
        st.warning("Nenhum operador com nome foi encontrado.")
        st.stop()

    summary = pd.DataFrame([
        {
            "Operador": r["nome"],
            "Aderência (%)": r["aderencia"],
            "Classificação aderência": r["classificacao_aderencia"],
            "Coerência (%)": r["coerencia"],
            "Classificação coerência": r["classificacao_coerencia"],
            "Consistência das respostas": r["consistencia_respostas"],
            "Reconhecimento": r["classificacao_reconhecimento"],
            "Motivos": " | ".join(r["motivos_reconhecimento"]),
        }
        for r in results
    ])

    st.subheader("Visão geral")
    st.dataframe(summary, use_container_width=True, hide_index=True)

    # Gráfico vertical: todos os nomes, com rolagem horizontal em telas estreitas.
    # Nenhuma nota, classificação ou regra do motor de avaliação é modificada.
    chart_df = summary[["Operador", "Aderência (%)", "Coerência (%)"]].melt(
        id_vars="Operador",
        value_vars=["Aderência (%)", "Coerência (%)"],
        var_name="Indicador", value_name="Pontuação (%)",
    )
    chart_df["Faixa de cor"] = chart_df["Pontuação (%)"].apply(
        lambda value: "Vermelho (até 50%)" if value <= 50
        else ("Laranja (acima de 50% e abaixo de 80%)" if value < 80
              else "Verde (80% ou mais)")
    )
    st.caption(
        "Verde: 80% ou mais · Laranja: acima de 50% e abaixo de 80% · "
        "Vermelho: 50% ou menos. Cada barra recebe a cor de sua própria pontuação. "
        "Role horizontalmente para visualizar todos os operadores."
    )
    # Exibe os 31 nomes sem omissão automática, mantendo as barras na vertical.
    # A largura acompanha a quantidade de operadores e evita sobreposição.
    operator_order = list(dict.fromkeys(summary["Operador"].astype(str)))
    chart_width = max(1000, len(operator_order) * 76)
    chart = (
        alt.Chart(chart_df)
        .mark_bar()
        .encode(
            x=alt.X(
                "Operador:N", title="Operador", sort=operator_order,
                axis=alt.Axis(
                    labelAngle=-55, labelOverlap=False, labelLimit=250,
                    labelFontSize=11, labelPadding=9,
                ),
            ),
            xOffset=alt.XOffset("Indicador:N", sort=["Aderência (%)", "Coerência (%)"]),
            y=alt.Y("Pontuação (%):Q", title="Pontuação (%)", scale=alt.Scale(domain=[0, 100])),
            color=alt.Color(
                "Faixa de cor:N",
                scale=alt.Scale(
                    domain=[
                        "Verde (80% ou mais)",
                        "Laranja (acima de 50% e abaixo de 80%)",
                        "Vermelho (até 50%)",
                    ],
                    range=["#159B54", "#F39C12", "#D83A3A"],
                ),
                legend=alt.Legend(title="Faixa de pontuação"),
            ),
            tooltip=["Operador:N", "Indicador:N", alt.Tooltip("Pontuação (%):Q", format=".1f")],
        )
        .properties(width=chart_width, height=380)
    )
    # Permite rolagem dentro do componente, sem comprimir as colunas do gráfico.
    st.markdown(
        """<style>
        div[data-testid="stVegaLiteChart"], div[data-testid="stAltairChart"] {
            overflow-x: auto !important;
            max-width: 100%;
        }
        </style>""",
        unsafe_allow_html=True,
    )
    st.altair_chart(chart, use_container_width=False)

    csv = summary.to_csv(index=False).encode("utf-8-sig")
    st.download_button("Baixar resumo em CSV", csv, file_name="resumo_avaliacao_auto_drill.csv", mime="text/csv")

    st.subheader("Classificação para reconhecimento")
    st.caption("Critério: aderência e coerência de pelo menos 80%, sem contradições relevantes, lacunas técnicas graves ou respostas essenciais pendentes. Não comprova aplicação em campo. A lista não é completada para atingir uma quantidade fixa.")
    counts = summary["Reconhecimento"].value_counts()
    for status in ("Elegível para reconhecimento", "Precisa de validação", "Não elegível nesta avaliação"):
        st.write(f"{status}: {counts.get(status, 0)}")
    eligible = summary[summary["Reconhecimento"] == "Elegível para reconhecimento"].sort_values(
        ["Coerência (%)", "Aderência (%)"], ascending=False)
    if eligible.empty:
        st.info("Nenhum operador atende a todos os critérios nesta avaliação.")
    else:
        st.dataframe(eligible, use_container_width=True, hide_index=True)
    st.download_button("Baixar elegíveis em CSV", eligible.to_csv(index=False).encode("utf-8-sig"),
                       file_name="elegiveis_reconhecimento_auto_drill.csv", mime="text/csv")

    # Ranking complementar: os oito menores resultados de aderência.
    # Não modifica notas, regras de coerência nem elegibilidade para reconhecimento.
    st.subheader("8 operadores com menor aderência ao Auto Drill")
    st.caption(
        "Lista ordenada pela menor pontuação de aderência. A coerência é exibida "
        "separadamente e não altera a posição neste ranking. "
        "Este resultado indica prioridades de acompanhamento, não comprova desempenho em campo."
    )
    least_adherent = (
        summary.sort_values(
            ["Aderência (%)", "Coerência (%)", "Operador"],
            ascending=[True, True, True],
            kind="stable",
        )
        .head(8)
        .copy()
    )
    if least_adherent.empty:
        st.info("Nenhum operador disponível para esta classificação.")
    else:
        st.dataframe(least_adherent, use_container_width=True, hide_index=True)
        st.download_button(
            "Baixar 8 menos aderentes em CSV",
            least_adherent.to_csv(index=False).encode("utf-8-sig"),
            file_name="8_menos_aderentes_auto_drill.csv",
            mime="text/csv",
        )

    st.divider()
    selected = st.selectbox("Selecione um operador para análise detalhada", [r["nome"] for r in results])
    r = next(x for x in results if x["nome"] == selected)

    st.subheader("Resultado para reconhecimento")
    st.write(r["classificacao_reconhecimento"])
    st.write(r["consistencia_respostas"])
    for reason in r["motivos_reconhecimento"]:
        st.write("• " + reason)

    c1, c2 = st.columns(2)
    with c1:
        st.metric("Aderência ao Auto Drill", f"{r['aderencia']:.1f}%", r["classificacao_aderencia"])
    with c2:
        st.metric("Coerência técnico-comportamental", f"{r['coerencia']:.1f}%", r["classificacao_coerencia"])

    st.subheader("Aderência — questão por questão")
    adf = pd.DataFrame(r["aderencia_detalhes"])
    adf["Pontuação"] = adf.apply(lambda x: f"{x['pontos']:.1f}/{x['max']:.1f}", axis=1)
    st.dataframe(adf[["questao", "resposta", "Pontuação", "leitura"]], use_container_width=True, hide_index=True)

    st.subheader("Coerência — cruzamentos lógicos")
    for f in r["coerencia_detalhes"]:
        icon = "✅" if f["severity"] == "nenhuma" else ("⚠️" if f["severity"] == "media" else "🔴")
        st.markdown(f"**{icon} {f['title']}** — {f['area']}")
        st.write(f["explanation"])
        st.caption(f"Pontuação de coerência neste critério: {f['score']}/{f['max_score']}")

    st.subheader("Respostas originais")
    with st.expander("Exibir respostas do operador"):
        st.json(r["_record"])

    st.info("Importante: a plataforma mede comportamento declarado e coerência das respostas. Para confirmar aplicação real, recomenda-se cruzar com acompanhamento em campo e dados do equipamento.")
else:
    st.info("Envie a planilha exportada do Microsoft Forms para iniciar a avaliação.")
